**Important Security Notes:**
1. Webcam hijacking is illegal and unethical
2. Modern browsers require explicit user permission for camera access
3. Always inform users when accessing their camera

**Legitimate Example: Camera Access with Permission**

```html
<!DOCTYPE html>
<html>
<head>
    <title>Camera Test</title>
</head>
<body>
    <h1>Camera Test Application</h1>
    <video id="video" width="640" height="480" autoplay></video>
    <br>
    <button id="start">Start Camera</button>
    <button id="capture">Capture Photo</button>
    <canvas id="canvas" style="display:none;"></canvas>

    <script>
        const video = document.getElementById('video');
        const canvas = document.getElementById('canvas');
        const startButton = document.getElementById('start');
        const captureButton = document.getElementById('capture');

        // Request camera access with user permission
        async function startCamera() {
            try {
                const stream = await navigator.mediaDevices.getUserMedia({ 
                    video: true,
                    audio: false 
                });
                video.srcObject = stream;
                console.log("Camera access granted");
            } catch (err) {
                console.error("Camera access denied:", err);
            }
        }

        // Capture photo from video feed
        function capturePhoto() {
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            const context = canvas.getContext('2d');
            context.drawImage(video, 0, 0);

            // Convert to image data URL
            const imageDataUrl = canvas.toDataURL('image/png');
            console.log("Photo captured:", imageDataUrl);

            // For demonstration only - normally you'd save or display the image
            alert("Photo captured! Check browser console for image data.");
        }

        startButton.addEventListener('click', startCamera);
        captureButton.addEventListener('click', capturePhoto);
    </script>
</body>
</html>
